using System.Data;using System.Data.Common;using Microsoft.EntityFrameworkCore;using TCT.LMS.Application.Interfaces.Repositories;using TCT.LMS.Data.Common;namespace TCT.LMS.Infrastructure.Repositories;
public sealed class RemainingDashboardRepository:IRemainingDashboardRepository{private readonly ApplicationDbContext _db;public RemainingDashboardRepository(ApplicationDbContext db)=>_db=db;public Task<IReadOnlyList<IReadOnlyDictionary<string,object?>>> QueryAsync(RemainingDashboardQuery q,DateTime f,DateTime t,int take,CancellationToken token)=>Run(Sql(q),f,t,take,token);
private static string Sql(RemainingDashboardQuery q)=>q switch{
RemainingDashboardQuery.FinanceSummary=>@"SELECT (SELECT COUNT_BIG(*) FROM dbo.StudentInvoice WHERE IsActive=1 AND CreatedDate>=@FromDate AND CreatedDate<DATEADD(day,1,@ToDate)) InvoiceCount,(SELECT ISNULL(SUM(TotalInvoiceAmount),0) FROM dbo.StudentInvoice WHERE IsActive=1 AND CreatedDate>=@FromDate AND CreatedDate<DATEADD(day,1,@ToDate)) InvoicedAmount,(SELECT ISNULL(SUM(p.Amount),0) FROM dbo.StudentPayment p WHERE p.IsActive=1 AND p.PaidDate>=@FromDate AND p.PaidDate<DATEADD(day,1,@ToDate)) CollectedAmount,(SELECT ISNULL(SUM(TutorTotalPayment),0) FROM dbo.TutorInvoice WHERE IsActive=1 AND CreatedDate>=@FromDate AND CreatedDate<DATEADD(day,1,@ToDate)) TutorPayable,(SELECT COUNT_BIG(*) FROM dbo.StudentInvoice WHERE IsActive=1 AND DueDate<GETDATE()) OverdueInvoices;",
RemainingDashboardQuery.FinanceTrend=>@"SELECT DATEFROMPARTS(Year,Month,1) ReportMonth,COUNT_BIG(*) Invoices,SUM(TotalInvoiceAmount) Revenue FROM dbo.StudentInvoice WHERE IsActive=1 AND DATEFROMPARTS(Year,Month,1)>=DATEFROMPARTS(YEAR(@FromDate),MONTH(@FromDate),1) AND DATEFROMPARTS(Year,Month,1)<=DATEFROMPARTS(YEAR(@ToDate),MONTH(@ToDate),1) GROUP BY Year,Month ORDER BY ReportMonth;",
RemainingDashboardQuery.OutstandingInvoices=>@"SELECT TOP (@Take) i.Id InvoiceId,i.InvoiceNumber,i.StudentId,COALESCE(u.FullName,CONCAT(u.FirstName,N' ',u.LastName)) StudentName,i.TotalInvoiceAmount,i.DueDate,DATEDIFF(day,i.DueDate,GETDATE()) DaysOverdue FROM dbo.StudentInvoice i JOIN dbo.Student st ON st.Id=i.StudentId JOIN dbo.[User] u ON u.Id=st.UserId WHERE i.IsActive=1 AND i.DueDate<GETDATE() ORDER BY i.DueDate;",
RemainingDashboardQuery.PaymentModes=>@"SELECT ISNULL(PaymentMode,N'Unspecified') PaymentMode,COUNT_BIG(*) Payments,SUM(Amount) Amount FROM dbo.StudentPayment WHERE IsActive=1 AND PaidDate>=@FromDate AND PaidDate<DATEADD(day,1,@ToDate) GROUP BY PaymentMode ORDER BY Amount DESC;",
RemainingDashboardQuery.HrSummary=>@"SELECT COUNT_BIG(*) TotalTutors,SUM(CASE WHEN t.IsActive=1 AND u.IsActive=1 THEN CONVERT(bigint,1) ELSE 0 END) ActiveTutors,SUM(CASE WHEN t.CreatedDate>=@FromDate AND t.CreatedDate<DATEADD(day,1,@ToDate) THEN CONVERT(bigint,1) ELSE 0 END) NewTutors,(SELECT COUNT_BIG(*) FROM dbo.TutorStudentAllocations WHERE IsActive=1 AND StatusCode=20012) PendingApprovals FROM dbo.Tutor t JOIN dbo.[User] u ON u.Id=t.UserId;",
RemainingDashboardQuery.TutorPipeline=>@"SELECT ISNULL(tc.TypeCodeName,N'Unclassified') Stage,COUNT(DISTINCT a.TutorId) Tutors FROM dbo.TutorStudentAllocations a LEFT JOIN dbo.Type_Code tc ON tc.TypeCodeValue=a.StatusCode WHERE a.IsActive=1 GROUP BY tc.TypeCodeName ORDER BY Tutors DESC;",
RemainingDashboardQuery.TutorOnboardingTrend=>@"SELECT DATEFROMPARTS(YEAR(t.CreatedDate),MONTH(t.CreatedDate),1) ReportMonth,COUNT_BIG(*) Tutors FROM dbo.Tutor t WHERE t.CreatedDate>=@FromDate AND t.CreatedDate<DATEADD(day,1,@ToDate) GROUP BY DATEFROMPARTS(YEAR(t.CreatedDate),MONTH(t.CreatedDate),1) ORDER BY ReportMonth;",
RemainingDashboardQuery.TutorEngagement=>@"SELECT TOP (@Take) t.Id TutorId,COALESCE(u.FullName,CONCAT(u.FirstName,N' ',u.LastName)) TutorName,u.JoiningDate,COUNT(DISTINCT CASE WHEN a.IsActive=1 THEN a.StudentId END) Students,CAST(AVG(CONVERT(decimal(10,2),r.Rating)) AS decimal(5,2)) Rating,CASE WHEN COUNT(DISTINCT CASE WHEN a.IsActive=1 THEN a.StudentId END)<=5 THEN N'Low' ELSE N'High' END Engagement FROM dbo.Tutor t JOIN dbo.[User] u ON u.Id=t.UserId LEFT JOIN dbo.TutorStudentAllocations a ON a.TutorId=t.Id LEFT JOIN dbo.UserClassRating r ON r.RatedUserId=u.Id GROUP BY t.Id,u.FullName,u.FirstName,u.LastName,u.JoiningDate ORDER BY Students DESC;",_=>throw new ArgumentOutOfRangeException(nameof(q),q,null)};
private async Task<IReadOnlyList<IReadOnlyDictionary<string,object?>>> Run(string sql,DateTime f,DateTime t,int take,CancellationToken token){DbConnection c=_db.Database.GetDbConnection();var o=c.State!=ConnectionState.Open;if(o)await c.OpenAsync(token);try{await using var cmd=c.CreateCommand();cmd.CommandText=sql;if(sql.Contains("@FromDate"))Add(cmd,"@FromDate",DbType.Date,f);if(sql.Contains("@ToDate"))Add(cmd,"@ToDate",DbType.Date,t);if(sql.Contains("@Take"))Add(cmd,"@Take",DbType.Int32,take);var rows=new List<IReadOnlyDictionary<string,object?>>();await using var r=await cmd.ExecuteReaderAsync(token);while(await r.ReadAsync(token)){var row=new Dictionary<string,object?>(r.FieldCount,StringComparer.OrdinalIgnoreCase);for(int i=0;i<r.FieldCount;i++)row[r.GetName(i)]=await r.IsDBNullAsync(i,token)?null:r.GetValue(i);rows.Add(row);}return rows;}finally{if(o)await c.CloseAsync();}}private static void Add(DbCommand c,string n,DbType t,object v){var p=c.CreateParameter();p.ParameterName=n;p.DbType=t;p.Value=v;c.Parameters.Add(p);}}
